-- Migración 027: añade campo 'uses' a cada output en forge_nodes (v1.4.0)
-- Solo modifica la columna outputs. No toca skills, prompts, inputs ni ningún otro campo.

UPDATE v57.forge_nodes SET outputs = '[{"key":"concept_seeds","type":"connection","label":"Concept Seeds","format":"structured","prompt":"Emit the curated concept seeds as structured data: id, title, one_liner, rationale for each.","image_gen":true,"image_gen_model":"comfyui:Character_Template_Generator","uses":{"inputs":[],"siblings_if_present":[]}},{"key":"exploration_summary","type":"asset","label":"Exploration Summary","format":"markdown","prompt":"Produce a markdown summary of the exploration: angles considered, seeds generated, rationale for each keep/cull.","uses":{"inputs":[],"siblings_if_present":[]}}]'::jsonb
WHERE node_key = '1.1' AND status = 'active';

UPDATE v57.forge_nodes SET outputs = '[{"key":"market_gap_analysis","type":"connection","label":"Market Gap Analysis","format":"gap_analysis","prompt":"Emit the market gap analysis as structured data: text summary and cultural_moment anchor.","uses":{"inputs":["concept_seeds"],"siblings_if_present":["competitive_scan"]}},{"key":"competitive_scan","type":"asset","label":"Competitive Scan","format":"markdown","prompt":"Produce a markdown table of 5–10 real titles with revenue, reviews, platform, and differentiators. Cite all sources.","uses":{"inputs":["concept_seeds"],"siblings_if_present":[]}},{"key":"audience_sizing","type":"asset","label":"Audience Sizing","format":"markdown","prompt":"Produce audience sizing: estimated addressable audience with methodology. Label as indicative if comparables-based.","uses":{"inputs":["concept_seeds"],"siblings_if_present":[]}}]'::jsonb
WHERE node_key = '1.2' AND status = 'active';

UPDATE v57.forge_nodes SET outputs = '[{"key":"positioning_statement","type":"connection","label":"Positioning Statement","format":"positioning","prompt":"Emit the positioning statement as structured data: ''For [audience] who [need], [project] is the [category] that [differentiator].''","uses":{"inputs":["concept_seeds","market_gap_analysis"],"siblings_if_present":[]}},{"key":"primary_persona","type":"asset","label":"Primary Persona","format":"markdown","prompt":"Produce the primary persona: name, age range, platforms, titles they love, motivations, and why this game fits them.","uses":{"inputs":["concept_seeds"],"siblings_if_present":[]}}]'::jsonb
