UPDATE v57.forge_nodes SET outputs = '[{"key":"elevator_line","type":"connection","label":"Elevator Line","format":"text","prompt":"Emit the locked elevator line as structured data: one sentence, no hedging.","uses":{"inputs":["concept_seed"],"siblings_if_present":["pitch_document"]}},{"key":"pitch_document","type":"asset","label":"Pitch Document","format":"docx","prompt":"Produce the one-page High-Level Pitch docx using V57 template: hook, elevator line, why now, production fit.","uses":{"inputs":["concept_seed","positioning_statement","market_gap_analysis"],"siblings_if_present":[]}}]'::jsonb
WHERE node_key = '2.1' AND status = 'active';

UPDATE v57.forge_nodes SET outputs = '[{"key":"concept_data","type":"connection","label":"Concept Data","format":"concept_data","prompt":"Emit the concept as structured data: title, one_liner, setting, core_fantasy, core_loop[], signature_mechanics[], differentiators[].","uses":{"inputs":["concept_seed"],"siblings_if_present":["concept_document"]}},{"key":"concept_document","type":"asset","label":"Concept Document","format":"docx","prompt":"Produce the two-page Concept Treatment docx using V57 template: Fact Sheet, One-Liner, Setting, Core Fantasy, Core Loop, Signature Mechanics, Levels, Art & Audio, Narrative Hook, Differentiators.","uses":{"inputs":["concept_seed","elevator_line","positioning_statement","market_gap_analysis"],"siblings_if_present":[]}}]'::jsonb
