UPDATE v57.forge_nodes SET outputs = '[{"key":"investor_deck","type":"asset","label":"Investor Deck","format":"pptx","prompt":"Produce the investor deck using V57 cinematic template. Structure: Cover, Elevator, Setting, Fantasy+Loop, Mechanics, World, Differentiators+Why Now, Business Model, Production Fit, Closing. Images from Visual Orientation; palette from locked palette.","uses":{"inputs":["concept_data","elevator_line","orientation_images","financial_case"],"siblings_if_present":[]}}]'::jsonb
