UPDATE v57.forge_nodes SET outputs = '[{"key":"review_verdict","type":"connection","label":"Review Verdict","format":"review_verdict","prompt":"Emit the review verdict as structured data: verdict (READY/CONDITIONS/NOT_READY), top_strengths[], top_risks[], coherence_ok.","uses":{"inputs":["investor_deck"],"siblings_if_present":["strategic_review"]}},{"key":"strategic_review","type":"asset","label":"Strategic Review","format":"markdown","prompt":"Produce the written strategic review: strengths with evidence, risks each with a mitigation, coherence audit across all artifacts, and final verdict with reasoning.","uses":{"inputs":["investor_deck","concept_data","financial_case"],"siblings_if_present":[]}}]'::jsonb
