UPDATE v57.forge_nodes SET outputs = '[{"key":"gate_decision","type":"connection","label":"Gate Decision","format":"decision","prompt":"Emit the gate decision as structured data: verdict (ACCEPT/REFINE/BRANCH/KILL), refine_nodes[] if applicable.","uses":{"inputs":["investor_deck","review_verdict"],"siblings_if_present":[]}},{"key":"locked_concept_package","type":"asset","label":"Locked Concept Package","format":"artifact_bundle","prompt":"If verdict is ACCEPT: produce the locked concept package bundling all approved artifacts. If not ACCEPT: skip this output.","uses":{"inputs":["investor_deck"],"siblings_if_present":["gate_decision"]}}]'::jsonb
